pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // The admin (and initial owner) is this test contract, since C stores
        // admin/owner = msg.sender at construction. No restriction needed on
        // newOwner beyond keeping it wide; the fuzzer explores the full domain.
        vm.assume(newOwner != address(0) || true); // keep domain fully wide

        // Drive c through setOwner from the admin.
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // General rule: a completed setOwner call always reports success=true.
        // The mutant instead returns owner == _owner, which is false whenever
        // newOwner differs from the owner at call time, so it violates the rule
        // for the (overwhelmingly likely) fuzzed input newOwner != old owner.
        assertTrue(ok, "setOwner must always return true");
    }
}

