// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, address actor) public {
        // Derive the candidate owner from a full-range fuzzed integer so the
        // zero case (seed == 0) is a trivially reachable point in the domain.
        address newOwner = address(uint160(seed));

        // The deployer (this test contract) is the admin, so only calls made
        // from this contract succeed; calls from any other actor revert in
        // both versions, so restrict to the admissible admin caller.
        vm.assume(actor == address(this));

        bool ok;
        bool ret;
        try c.setOwner(newOwner) returns (bool s) {
            ok = true;
            ret = s;
        } catch {
            ok = false;
            ret = true;
        }

        // General rule: any completed setOwner call succeeds AND returns true,
        // for every possible owner value including address(0).
        assertTrue(ok && ret);
    }
}

